{
 "genere": "prevedi",
 "titolo": "Previsioni sulla telecamera",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> bool:
	var cam := Camera2D.new()
	cam.position_smoothing_enabled = true
	return cam.position_smoothing_enabled
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "La proprietà `position_smoothing_enabled` viene impostata a `true` sullo script della telecamera e viene restituita direttamente."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var rect := Rect2i(2, 4, 10, 8)
	var tile_size := Vector2i(16, 16)
	var limit_left := rect.position.x * tile_size.x
	return limit_left
",
   "domanda": "Quanto vale `limit_left` restituito da `run()`?",
   "spiegazione": "`rect.position.x` è 2, e la dimensione del tile in orizzontale (`tile_size.x`) è 16. 2 per 16 fa 32."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var rect := Rect2i(0, 0, 20, 15)
	var tile_size := Vector2i(32, 32)
	var limit_bottom := rect.end.y * tile_size.y
	return limit_bottom
",
   "domanda": "Quanto vale `limit_bottom` restituito da `run()`?",
   "spiegazione": "In un `Rect2i`, `rect.end` è la somma di `position` e `size`. Perciò `end.y` è `0 + 15 = 15`. Moltiplicato per l'altezza del tile (32), il risultato è 480."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var rect := Rect2i(5, 5, 10, 10)
	return rect.size.x
",
   "domanda": "Quanto vale `rect.size.x`?",
   "spiegazione": "La dimensione (`size`) del rettangolo è indipendente dalla sua posizione iniziale. `rect.size.x` vale 10, non 15."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var cam := Camera2D.new()
	cam.position_smoothing_speed = 4.0
	cam.position_smoothing_speed *= 2.0
	return cam.position_smoothing_speed
",
   "domanda": "Che valore restituisce `run()`?",
   "spiegazione": "La velocità di ammorbidimento parte da 4.0 e viene moltiplicata per 2.0, risultando in 8.0."
  }
 ]
